import { HolidayNotice } from "@/components/HolidayNotice";
import Link from "@/components/ui/Link";
import { DateNav } from "@/components/ui/DateNav";
import { getCompany } from "@/lib/company";
import { allOrders, pickDate, visibleDates } from "@/demo/all-orders";
import { dayCostSummary } from "@/lib/cost";
import { CostBox } from "@/components/ui/CostBox";
import { addDays, fmtDate, choiceClass } from "@/components/ui";
import { runPipeline } from "@/lib/pipeline";
import { countsInTotals, deliveryDatesOf } from "@/lib/aggregate";
import { findSupplier } from "@/lib/catalog";
import { methodLabel, type PurchaseOrderDraft } from "@/lib/purchase";
import { listPurchaseOrders } from "@/lib/purchase-store";
import { nowMs } from "@/lib/clock";
import { PurchaseClient, type PoView } from "./PurchaseClient";
import { loadMasters } from "@/lib/masters/seed-db";
import { findProduct, withMasters } from "@/lib/catalog";
import { purchaseTotalsForDate } from "@/lib/purchase";
import { checkPurchaseTotals } from "@/lib/purchase-check";
import { TotalsCheck } from "./TotalsCheck";

export const metadata = { title: "発注書｜STAFFETTA" };

const round = (n: number) => Math.round(n * 10) / 10;

export default async function PurchasePage(props: PageProps<"/purchase">) {
  const q = await props.searchParams;
  const { orders, today } = await allOrders();
  const tomorrow = addDays(today, 1);
  const dates = visibleDates(deliveryDatesOf(orders), today);
  const date = pickDate(q.date, dates, today);

  // 発注書の下書きは③（src/lib）が作る。画面は表示と、人の承認・送信の操作だけ
  const masters = await loadMasters(); // マスタ画面で直した値で計算（③の loadMasters）
  const r = runPipeline(orders, date, { masters });
  // 取引先の名前はマスタ（DB）から（見本の固定の一覧ではなく。3100 の本当の取引先も名前で出す）
  const customerName = new Map((masters.customers ?? []).map((c) => [c.id, c.name]));
  const shortage = new Map(r.shortages.map((s) => [s.materialId, s]));
  // 承認・送信済みの記録は③の purchase-store から（承認済みのものは中身も保存した方を見せる）
  const stored = new Map((await listPurchaseOrders()).map((p) => [p.id, p]));

  const view = (po: PurchaseOrderDraft): PoView => {
    const s = withMasters(masters, () => findSupplier(po.supplierId));
    return {
      id: po.id,
      supplierName: po.supplierName,
      method: po.method,
      methodText: po.siteName ?? methodLabel(po.method),
      contact: s?.contact ?? "",
      deliveryName: po.deliveryName,
      cutoffAt: po.cutoffAt,
      deliveryDate: po.deliveryDate,
      kind: po.kind,
      notes: po.notes,
      state: (() => {
        const s = stored.get(po.id);
        return s ? { status: s.status, approvedBy: s.approvedBy, approvedAt: s.approvedAt, sentAt: s.sentAt, sentBy: s.sentBy, sentVia: s.sentVia } : { status: "draft" as const };
      })(),
      lines: po.lines.map((l) => {
        let detail: string | undefined;
        if (l.itemType === "product" && l.customers?.length) {
          const per = l.customers.map((c) => `${customerName.get(c.customerId) ?? c.customerId} ${c.pieces}個→${c.packs}${l.unitLabel === "個" ? "個" : "袋"}`).join("／");
          // ⑧ 事業所から来る包装ごとの数（1個包装 ◯・2個包装 ◯）→ 合わせて ◯個 → 6個入り ◯袋（前は電卓で出していた）
          const packs = new Map<string, number>();
          for (const o of orders) {
            if (o.deliveryDate !== date || !countsInTotals(o) || !l.customers.some((c) => c.customerId === o.customerId)) continue;
            for (const ol of o.lines) if (ol.productId === l.itemId) packs.set(ol.unit || "個", (packs.get(ol.unit || "個") ?? 0) + ol.quantity);
          }
          // 包装が2つ以上なら、その式だけ（ほかの文は出さない。担当者「意味が分からない」）
          detail = packs.size > 1
            ? `${[...packs].map(([u, q]) => `${u} ${q}`).join(" ＋ ")} ＝ ${l.needQuantity}個 → ${l.unitLabel === "個" ? `${l.units}個` : `${l.unitLabel} ${l.units}袋`}`
            : `注文 ${l.needQuantity}個${l.surplus ? `（余り ${l.surplus}個）` : ""}　${per}${l.notes?.length ? `　${l.notes.join("・")}` : ""}`;
        } else if (l.notes?.length) {
          detail = l.notes.join("・");
        } else if (l.itemType === "material") {
          const sh = shortage.get(l.itemId);
          detail = sh
            ? `使う量 ${round(sh.needUnits)}${sh.unit}・在庫 ${round(sh.stock)}${sh.unit}・安全在庫 ${round(sh.safetyStock)}${sh.unit}`
            : `使う量 ${round(l.needQuantity)}`;
        }
        return { name: l.name, units: l.units, unitLabel: l.itemType === "product" && l.unitLabel.endsWith("入") ? `袋（${l.unitLabel}）` : l.unitLabel, detail };
      }),
    };
  };
  // 承認後に注文が変わっても、承認した中身（保存したもの）を見せる
  const drafts = [...r.productPurchaseOrders, ...r.materialPurchaseOrders].map((d) => {
    const s = stored.get(d.id);
    return s && s.status !== "draft" ? ({ ...d, lines: s.lines as typeof d.lines } as PurchaseOrderDraft) : d;
  });
  const pos = drafts.filter((p) => p.lines.length > 0).map(view);
  // ⑧ C 発注の合計と注文の合計の照らし合わせ（承認・送信のあとに注文が変わった・仕入品がどの発注書にも入っていない）
  const buyOrdered = withMasters(masters, () =>
    purchaseTotalsForDate(orders, date).products.filter((p) => {
      const spec = findProduct(p.productId)?.spec;
      return spec?.kind === "buy" && !spec.slicesPerItem;
    }),
  ).map((p) => ({ productId: p.productId, name: p.name, pieces: p.pieces }));
  const check = checkPurchaseTotals(r.productPurchaseOrders, [...stored.values()].filter((s) => s.deliveryDate === date), buyOrdered);

  return (
    <>
      <HolidayNotice dates={[{ date, label: "届けてほしい日" }]} what="仕入先が届けられるか、届く日を確かめてください。" />
      <PurchaseClient
        pos={pos}
        date={date}
        factory={getCompany().name}
        warnings={r.warnings}
        serverNow={nowMs()}
        lateMaterials={r.materialPlan.lateItems.map((x) => x.message)}
        lateRows={r.materialPlan.lateItems.map((x) => ({
          name: x.name,
          amount: `${Math.round(x.shortUnits * 10) / 10}${x.unit}`,
          day: `${Number(x.productionDate.slice(5, 7))}/${Number(x.productionDate.slice(8, 10))}`,
          supplier: x.supplierName.replace(/（[^）]*）/g, ""),
        }))}
        needOrder={new Set(r.materialPurchaseOrders.flatMap((p) => p.lines.map((l) => l.itemId))).size}
        unconfirmed={orders.filter((o) => o.deliveryDate === date && (o.status === "needs_review" || o.status === "provisional")).length}
        costBox={
          <>
            <TotalsCheck rows={check} />
            <div className="max-md:hidden"><CostBox s={withMasters(masters, () => dayCostSummary(r))} show={["purchase", "material"]} /></div>
          </>
        }
      dateNav={
        dates.length > 0 && (
          <>
          <DateNav date={date} today={today} pattern="/purchase?date=__DATE__" marks={dates} />
          <div className="flex flex-wrap items-center gap-2 max-md:hidden">
            <span className="text-sm font-bold text-ink-soft">納品日</span>
            {dates.map((d) => (
              <Link
                key={d}
                href={`/purchase?date=${d}`}
                className={choiceClass(d === date, "num inline-flex min-h-12 items-center px-4")}
              >
                {fmtDate(d)}
                {d === tomorrow && <span className="ml-1.5 text-sm opacity-75">明日</span>}
              </Link>
            ))}
          </div>
          </>
        )
      }
    />
    </>
  );
}
